import {defaults,freshTimer,remaining,toggleTimer,advance,nextMode,takeCompletion,formatTime,dayKey} from './core.js';
const $=s=>document.querySelector(s);
const paths={tide:'M3 9c4-6 6 6 10 0s6 0 8 0M3 15c4-6 6 6 10 0s6 0 8 0',clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',timer:'M9 2h6M12 6v2m6-3 2 2M21 14a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 10v5l3 1',check:'m6 12 4 4 8-8M8 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',arrow:'M5 12h14m-5-5 5 5-5 5',plus:'M12 5v14M5 12h14',return:'M19 5v8H5m5-5-5 5 5 5',pip:'M9 19H4a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1h16a1 1 0 0 1 1 1v4M12 12h9v7h-9z',play:'m8 5 11 7-11 7z',pause:'M8 5v14M16 5v14',reset:'M3 10a9 9 0 1 1 2 9M3 4v6h6',skip:'m5 5 9 7-9 7zM18 5v14',close:'m6 6 12 12M6 18 18 6',lock:'M6 10h12v10H6zM8 10V7a4 4 0 0 1 8 0v3',sparkles:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7M20 2v4m-2-2h4',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',leaf:'M20 3C4 1 1 14 9 18c7 5 13-2 11-15M5 21 16 9'};
function icon(n){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.clock}"/></svg>`;}
function paintIcons(root=document){root.querySelectorAll('[data-icon]').forEach(x=>x.innerHTML=icon(x.dataset.icon));}
paintIcons();
const STORAGE='tide-clock-v1';let storageWarning=false;
function load(){try{return JSON.parse(localStorage.getItem(STORAGE)||'{}');}catch{return {};}}
const saved=load();let settings={...defaults,...saved.settings};
if((saved.settings?.homeLayoutVersion||0)<2){if(!saved.settings?.colorClock||saved.settings.colorClock.toLowerCase()==='#ff6669')settings.colorClock='#ffffff';settings.homeLayoutVersion=2;}
for(const [k,max] of Object.entries({work:180,short:60,long:120,interval:6})){if(!Number.isFinite(settings[k])||settings[k]<1||settings[k]>max)settings[k]=defaults[k];}
for(const k of ['colorClock','colorWork','colorShort','colorLong']){if(!/^#[0-9a-f]{6}$/i.test(settings[k]))settings[k]=defaults[k];}
let tasks=Array.isArray(saved.tasks)?saved.tasks.filter(x=>typeof x.text==='string'&&typeof x.id==='string'):[];
let history=Array.isArray(saved.history)?saved.history:[];
let timer=saved.timer&&['work','short','long'].includes(saved.timer.mode)&&Number.isFinite(saved.timer.remaining)&&(!saved.timer.running||Number.isFinite(saved.timer.deadline))?saved.timer:freshTimer(settings);
let pendingSummary=saved.pendingSummary||null;
let view='clock',filter='all',selectedTask=saved.selectedTask||null,pipWindow=null,pipVideo=null,pipCanvas=null,pipStream=null,toastTimeout,summaryTimerId=null,wakeLock=null,audioContext;
const stageNames={work:'专注',short:'短休息',long:'长休息'};
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({settings,tasks,history,timer,pendingSummary,selectedTask}));}catch{if(!storageWarning){storageWarning=true;toast('浏览器存储空间不可用，本次修改暂时无法保存。');}}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function setView(next){view=next;document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!==`${next}-view`);document.querySelectorAll('.main-nav [data-view]').forEach(x=>{x.classList.toggle('active',x.dataset.view===next);x.setAttribute('aria-current',x.dataset.view===next?'page':'false');});if(next==='plans'){document.body.classList.remove('zen');renderTasks();}applyTheme();renderTimer();}
function palette(stage,prefs=settings){
 const key={clock:'colorClock',work:'colorWork',short:'colorShort',long:'colorLong'}[stage]||'colorClock';
 let rgb=prefs[key].slice(1).match(/../g).map(v=>parseInt(v,16));
 if(prefs.theme==='dark')rgb=rgb.map(v=>Math.round(v*.26));
 const bg='#'+rgb.map(v=>v.toString(16).padStart(2,'0')).join('');
 const l=rgb.map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4;}).reduce((a,v,i)=>a+v*[.2126,.7152,.0722][i],0);
 const light=l<.179;return {bg,text:light?'#ffffff':'#241c1d',muted:light?'rgba(255,255,255,.78)':'rgba(36,28,29,.72)',glass:light?'rgba(0,0,0,.16)':'rgba(255,255,255,.18)',line:light?'rgba(255,255,255,.2)':'rgba(36,28,29,.16)'};
}
function paintPalette(body,stage,prefs=settings){const p=palette(stage,prefs);for(const [k,v]of Object.entries(p))body.style.setProperty('--'+k,v);body.style.setProperty('--accent',p.text);body.style.setProperty('--accent-strong',p.text);body.style.setProperty('--white',p.glass);}
function applyTheme(prefs=settings){document.body.classList.toggle('dark',prefs.theme==='dark');document.body.dataset.stage=view==='focus'?timer.mode:'clock';document.body.dataset.view=view;paintPalette(document.body,document.body.dataset.stage,prefs);$('#theme-btn').innerHTML=icon(prefs.theme==='dark'?'sun':'moon');document.querySelector('meta[name="theme-color"]').content=palette(document.body.dataset.stage,prefs).bg;if(pipWindow&&!pipWindow.closed){pipWindow.document.body.classList.toggle('dark',prefs.theme==='dark');pipWindow.document.body.dataset.stage=timer.mode;paintPalette(pipWindow.document.body,timer.mode,prefs);}}

function activeTask(){return tasks.find(x=>x.id===selectedTask&&!x.done)||tasks.find(x=>!x.done);}
function renderTasks(){const done=tasks.filter(x=>x.done).length;$('#nav-count').textContent=tasks.length-done;$('#plan-progress').textContent=`${done} / ${tasks.length}`;$('#full-progress').textContent=`${done} / ${tasks.length}`;
function draw(target,list,empty){target.replaceChildren();if(!list.length){const el=document.createElement('div');el.className='empty-tasks';el.innerHTML=icon('leaf');const text=document.createElement('span');text.textContent=empty;el.append(text);target.append(el);return;}list.forEach(t=>{const row=document.createElement('div');row.className=`task-row${t.done?' done':''}`;const label=document.createElement('label');const cb=document.createElement('input');cb.type='checkbox';cb.checked=t.done;cb.setAttribute('aria-label',`完成计划：${t.text}`);cb.addEventListener('change',()=>{t.done=cb.checked;t.doneAt=t.done?Date.now():null;persist();renderTasks();renderTimer();});const text=document.createElement('span');text.className='task-text';text.textContent=t.text;label.append(cb,text);const focus=document.createElement('button');focus.className='task-focus';focus.innerHTML=icon('timer');focus.title='专注于此计划';focus.setAttribute('aria-label',`专注于：${t.text}`);focus.onclick=()=>{selectedTask=t.id;persist();setView('focus');};const del=document.createElement('button');del.className='task-delete';del.innerHTML=icon('close');del.setAttribute('aria-label',`删除计划：${t.text}`);del.onclick=()=>{const index=tasks.indexOf(t);tasks.splice(index,1);persist();renderTasks();renderTimer();showUndo(t,index);};row.append(label,focus,del);target.append(row);});}
const quick=tasks.filter(t=>!t.done).concat(tasks.filter(t=>t.done&&!settings.hideDone));draw($('#quick-tasks'),quick,tasks.length?'计划都完成了，留点时间给自己。':'从一件小事开始，让今天有所期待。');draw($('#all-tasks'),tasks.filter(t=>filter==='all'||(filter==='done'?t.done:!t.done)),filter==='done'?'每一次勾选，都是一个小小的进步。':'这里很安静，写下你的第一个计划吧。');renderStats();}
function showUndo(t,index){toast('计划已移除');const b=document.createElement('button');b.textContent='撤销';b.style.cssText='color:#fac7a8;margin-left:15px;text-decoration:underline';b.onclick=()=>{tasks.splice(index,0,t);persist();renderTasks();toast('已恢复计划');};$('#toast').append(b);}
for(const id of ['quick-form','plan-form']){$(`#${id}`).addEventListener('submit',e=>{e.preventDefault();const input=e.currentTarget.querySelector('input');const value=input.value.trim();if(!value)return;tasks.push({id:crypto.randomUUID(),text:value,done:false,createdAt:Date.now(),doneAt:null});input.value='';persist();renderTasks();renderTimer();});}
function renderStats(){const today=dayKey();const rounds=history.filter(x=>x.mode==='work'&&dayKey(x.at)===today);const minutes=Math.round(rounds.reduce((a,x)=>a+x.duration,0)/60000);$('#stats-minutes').textContent=minutes;$('#stats-rounds').textContent=rounds.length;$('#stats-tasks').textContent=tasks.filter(x=>x.done&&dayKey(x.doneAt)===today).length;$('#footer-stats').textContent=rounds.length?`今日已专注 ${minutes} 分钟 · 完成 ${rounds.length} 个番茄`:'今天，给专注一点时间';}
function renderClock(){const d=new Date();const h=d.getHours();$('#hours').textContent=String(settings.hour12?(h%12||12):h).padStart(2,'0');$('#minutes').textContent=String(d.getMinutes()).padStart(2,'0');$('#clock').setAttribute('aria-label','当前时间 '+d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:settings.hour12}));}

function timerText(ms){if(settings.display==='approx')return ms<0?`+${Math.ceil(-ms/60000)} 分钟`:`${Math.ceil(ms/60000)} 分钟`;if(settings.display==='percent')return `${ms<0?'+':''}${Math.round((ms<0?-ms:timer.duration-ms)/timer.duration*100)}%`;return formatTime(ms);}
function renderTimer(){const upcoming=nextMode(timer,settings);
$('#mini-task-label').textContent=timer.mode==='work'?'当前计划':'休息时间';
$('#mini-task').textContent=timer.mode==='work'?(activeTask()?.text||'一次只做一件事，就是很好的开始。'):'站起来，伸个懒腰，喝一杯水。';
$('#mini-round').textContent='第 '+(timer.mode==='work'?timer.round+1:Math.max(1,timer.round))+' 轮';
$('#mini-next').textContent=stageNames[upcoming]+' · '+settings[upcoming]+' 分钟';
const left=remaining(timer);const value=timerText(left);$('#timer-number').textContent=value;$('#timer-number').classList.toggle('approx',settings.display==='approx');$('#mini-time').textContent=formatTime(left);$('#timer-progress').style.width=`${Math.min(100,Math.max(0,1-left/timer.duration)*100)}%`;$('#focus-label').textContent=`第 ${(timer.mode==='work'?timer.round+1:Math.max(1,timer.round))} 轮${stageNames[timer.mode]} · ${left<0?'已到时间，随时可以休息':timer.mode==='work'?'心无旁骛':'给自己充充电'}`;const label=timer.running?'暂停':timer.handled?(settings.end==='stop'?'查看本轮总结':'继续超时计时'):`开始${stageNames[timer.mode]}`;$('#start-btn').innerHTML=icon(timer.running?'pause':'play')+`<span>${label}</span>`;$('#mini-start').innerHTML=icon(timer.running?'pause':'play');$('#mini-start').setAttribute('aria-label',label);$('#mini-description').textContent=timer.running?`${stageNames[timer.mode]}中 · 按自己的节奏前进`:`给自己 ${Math.round(timer.duration/60000)} 分钟，${timer.mode==='work'?'做好一件事':'好好休息一下'}`;$('#active-task').textContent=timer.mode==='work'?(activeTask()?.text||'一次只做一件事，就是很好的开始。'):'站起来，伸个懒腰，喝一杯水。';$('#round-dots').innerHTML=Array.from({length:settings.interval},(_,i)=>`<span class="${i<timer.round%settings.interval?'done':''}"></span>`).join('');document.querySelectorAll('[data-mode]').forEach(x=>{x.classList.toggle('active',x.dataset.mode===timer.mode);x.setAttribute('aria-pressed',String(x.dataset.mode===timer.mode));});renderSchedule();if(view==='focus')document.title=`${formatTime(left)} · ${stageNames[timer.mode]} — Tide`;else document.title='Tide · 此刻';updatePip();}
let lastSchedule='';function renderSchedule(){const code=[timer.mode,timer.round,settings.work,settings.short,settings.long,settings.interval].join();if(code===lastSchedule)return;lastSchedule=code;let t={...timer},html='';for(let i=0;i<4;i++){html+=`${i?'<span class="schedule-arrow">›</span>':''}<span class="schedule-item ${i===0?'active':''}"><i></i>${stageNames[t.mode]} <small>${settings[t.mode]} 分钟</small></span>`;t.handled=true;t=advance(t,settings);}$('#schedule').innerHTML=html;}
async function lockScreen(){try{if(timer.running&&document.visibilityState==='visible'&&!wakeLock)wakeLock=await navigator.wakeLock?.request('screen');else if(!timer.running&&wakeLock){await wakeLock.release();wakeLock=null;}}catch{}}
function unlockAudio(){try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});}catch{}}
function chime(){if(!settings.sound)return;try{unlockAudio();const ctx=audioContext;[523.25,659.25,783.99].forEach((f,i)=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.connect(gain);gain.connect(ctx.destination);osc.frequency.value=f;gain.gain.setValueAtTime(0,ctx.currentTime+i*.16);gain.gain.linearRampToValueAtTime(.12,ctx.currentTime+i*.16+.015);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.16+.8);osc.start(ctx.currentTime+i*.16);osc.stop(ctx.currentTime+i*.16+.85);});}catch{}}
function toggle(){tick();unlockAudio();if(timer.handled&&settings.end==='stop'){const report=history.findLast(x=>x.id===`${timer.startedAt}-${timer.mode}`);if(report){pendingSummary=report;openSummary(report);persist();return;}}toggleTimer(timer);persist();renderTimer();lockScreen();}
function changeMode(mode){timer={...freshTimer(settings,mode),round:timer.round};pendingSummary=null;persist();applyTheme();renderTimer();lockScreen();}
function goNext(start=false){timer=advance(timer,settings);if(start){toggleTimer(timer);unlockAudio();}pendingSummary=null;persist();renderTasks();applyTheme();renderTimer();lockScreen();}
function tick(){const report=takeCompletion(timer,tasks);if(report){history.push(report);if(history.length>1000)history=history.slice(-1000);pendingSummary=report;const behavior=settings.end;if(behavior==='stop'){timer.remaining=0;timer.running=false;timer.deadline=null;}if(behavior==='advance'){timer=advance(timer,settings);toggleTimer(timer);}summaryTimerId=behavior==='advance'?null:report.id;persist();renderStats();applyTheme();openSummary(report);chime();notify(report);if(settings.fireworks&&report.mode==='work')fireworks();lockScreen();}renderClock();renderTimer();}
function openSummary(report){summaryTimerId=timer.startedAt===Number(report.id.split('-')[0])?report.id:null;$('#summary-title').textContent=report.mode==='work'?'又向前了一小步':'休息好了，再出发';$('#summary-description').textContent=report.mode==='work'?`完成了 ${Math.round(report.duration/60000)} 分钟专注，本轮完成 ${report.completed.length} 项计划。`:`完成了 ${Math.round(report.duration/60000)} 分钟${stageNames[report.mode]}。让我们带着新的能量继续。`;$('#summary-tasks').replaceChildren();report.completed.forEach(t=>{const el=document.createElement('div');el.className='summary-task';el.innerHTML=icon('check');const sp=document.createElement('span');sp.textContent=t.text;el.append(sp);$('#summary-tasks').append(el);});$('#relax-note').innerHTML=report.mode==='work'?'放松一下肩膀，看看远处。<br>休息，也是专注的一部分。':'选一件重要的事，<br>给它一段不被打扰的时间。';$('#summary-next').textContent=settings.end==='advance'?'继续当前阶段':report.mode==='work'?'开始休息':'开始下一轮专注';if(!$('#summary-dialog').open)$('#summary-dialog').showModal();updatePip();}
function notify(report){if(settings.notifications&&'Notification'in window&&Notification.permission==='granted'){try{new Notification(report.mode==='work'?'专注完成，休息一下吧 ☀':'充电完成，可以开始下一轮了',{body:report.mode==='work'?`本轮完成 ${report.completed.length} 项计划。站起来，喝点水。`:'选一件重要的事，慢慢来。',icon:'icon.svg',tag:'tide-session'});}catch{}}}
function fireworks(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const canvas=$('#fireworks'),ctx=canvas.getContext('2d');canvas.width=innerWidth*devicePixelRatio;canvas.height=innerHeight*devicePixelRatio;ctx.scale(devicePixelRatio,devicePixelRatio);const particles=[];for(let burst=0;burst<5;burst++){const x=innerWidth*(.15+Math.random()*.7),y=innerHeight*(.18+Math.random()*.4);for(let i=0;i<40;i++){const a=Math.random()*Math.PI*2,v=1+Math.random()*4;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,delay:burst*180,life:1,c:['#ed816d','#d9b678','#99af91','#c6b5d8'][i%4]});}}const start=performance.now();function frame(now){ctx.clearRect(0,0,innerWidth,innerHeight);particles.forEach(p=>{if(now-start<p.delay)return;p.x+=p.vx;p.y+=p.vy;p.vy+=.035;p.life-=.009;ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.c;ctx.fillRect(p.x,p.y,3,3);});ctx.globalAlpha=1;if(now-start<2600)requestAnimationFrame(frame);else ctx.clearRect(0,0,innerWidth,innerHeight);}requestAnimationFrame(frame);}
function openSettings(){const form=$('#settings-form');for(const [k,v]of Object.entries(settings)){const el=form.elements.namedItem(k);if(!el)continue;if(el.type==='checkbox')el.checked=v;else el.value=v;}updateNotificationStatus();$('#settings-dialog').showModal();}
$('#settings-dialog').addEventListener('close',()=>applyTheme());
const colorNames=['colorClock','colorWork','colorShort','colorLong'];
function previewPalette(){const f=$('#settings-form');const preview={...settings};for(const k of colorNames)preview[k]=f.elements.namedItem(k).value;applyTheme(preview);}
colorNames.forEach(k=>$('#settings-form').elements.namedItem(k).addEventListener('input',previewPalette));
document.querySelectorAll('[data-palette]').forEach(b=>b.onclick=()=>{const sets={classic:['#ffffff','#ff6669','#35d49a','#619dff'],vivid:['#ff6669','#ff6669','#35d49a','#619dff'],ocean:['#43c9ed','#43c9ed','#3bd2b0','#697cfa'],orchid:['#c888f1','#c888f1','#fba56d','#788cfa']};colorNames.forEach((k,i)=>$('#settings-form').elements.namedItem(k).value=sets[b.dataset.palette][i]);previewPalette();});
function updateNotificationStatus(){$('#notification-status').textContent=!('Notification'in window)?'此浏览器不支持':Notification.permission==='granted'?(settings.notifications?'已开启 · 点击关闭':'已授权 · 点击开启'):Notification.permission==='denied'?'已被浏览器阻止':'点击开启 →';}
$('#settings-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;for(const k of Object.keys(settings)){const el=f.elements.namedItem(k);if(!el)continue;settings[k]=el.type==='checkbox'?el.checked:el.type==='number'||k==='interval'?Number(el.value):el.value;}if(!timer.running&&timer.startedAt===null)timer={...freshTimer(settings,timer.mode),round:timer.round};persist();applyTheme();renderTasks();renderTimer();renderClock();$('#settings-dialog').close();toast('节奏已保存，按你的步调来。');});
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const vals=b.dataset.preset.split(',');['work','short','long'].forEach((n,i)=>$('#settings-form').elements.namedItem(n).value=vals[i]);});
$('#notification-btn').onclick=async()=>{if(!('Notification'in window)){toast('此浏览器不支持桌面通知，结束时仍会显示总结。');return;}if(Notification.permission==='denied'){toast('请在浏览器地址栏的网站权限中允许通知。');return;}try{const p=await Notification.requestPermission();settings.notifications=p==='granted'?!settings.notifications:false;persist();updateNotificationStatus();}catch{toast('通知暂时不可用，结束时仍会显示总结。');}};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();setView('clock');};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(timer.mode!==b.dataset.mode){if(timer.running){toast('已切换阶段，上一阶段不计入完成番茄。');}changeMode(b.dataset.mode);}});
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderTasks();});
$('#clear-done').onclick=()=>{const removed=tasks.filter(t=>t.done);if(!removed.length){toast('还没有已完成的计划，慢慢来。');return;}tasks=tasks.filter(t=>!t.done);persist();renderTasks();toast(`已清理 ${removed.length} 项已完成计划`);const b=document.createElement('button');b.textContent='撤销';b.style.cssText='color:#fac7a8;margin-left:15px;text-decoration:underline';b.onclick=()=>{tasks.push(...removed);persist();renderTasks();toast('已恢复计划');};$('#toast').append(b);};
$('#theme-btn').onclick=()=>{settings.theme=settings.theme==='dark'?'light':'dark';persist();applyTheme();};$('#settings-btn').onclick=openSettings;$('#start-btn').onclick=toggle;$('#mini-start').onclick=toggle;
$('#reset-btn').onclick=()=>{const round=timer.round;timer={...freshTimer(settings,timer.mode),round};pendingSummary=null;persist();renderTimer();lockScreen();toast('这一段时间，重新开始。');};$('#skip-btn').onclick=()=>{goNext(false);toast('已进入下一阶段，点击开始继续。');};
$('#summary-next').onclick=()=>{const auto=settings.end==='advance';$('#summary-dialog').close();if(!auto&&summaryTimerId){goNext(true);}else if(!timer.running){toggle();}pendingSummary=null;persist();};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));$('#summary-dialog').addEventListener('close',()=>{pendingSummary=null;persist();});
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('当前窗口不支持全屏。请在独立浏览器中打开，或使用 F11。');}}
$('#fullscreen-btn').onclick=fullscreen;document.addEventListener('fullscreenchange',()=>$('#fullscreen-btn').setAttribute('aria-label',document.fullscreenElement?'退出全屏':'进入全屏'));$('#zen-btn').onclick=()=>{if(view==='plans')setView('clock');document.body.classList.toggle('zen');toast(document.body.classList.contains('zen')?'已进入沉浸模式，按 Esc 恢复控件':'已退出沉浸模式');};
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,button')||document.querySelector('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();toggle();}if(e.key.toLowerCase()==='f')fullscreen();if(e.key==='Escape')document.body.classList.remove('zen');});
document.addEventListener('visibilitychange',()=>{if(wakeLock?.released)wakeLock=null;tick();lockScreen();});window.addEventListener('pagehide',persist);window.addEventListener('storage',e=>{if(e.key===STORAGE)toast('另一个窗口修改了数据。请在一个主页面中使用计时器。');});
async function openPip(){unlockAudio();try{if(pipWindow&&!pipWindow.closed){pipWindow.focus();return;}if('documentPictureInPicture'in window){pipWindow=await window.documentPictureInPicture.requestWindow({width:340,height:330});const doc=pipWindow.document;doc.title='Tide · 专注小窗';const link=doc.createElement('link');link.rel='stylesheet';link.href=new URL('style.css',location.href).href;doc.head.append(link);const appearance=doc.createElement('link');appearance.rel='stylesheet';appearance.href=new URL('appearance.css',location.href).href;doc.head.append(appearance);doc.body.className='pip-body';doc.body.innerHTML=`<main class="pip-wrap"><div class="pip-head"><span class="coral-dot"></span><span id="pip-stage">专注</span></div><div id="pip-time" class="pip-time"></div><div id="pip-task" class="pip-task"></div><div class="pip-controls"><button id="pip-toggle" class="start-button primary"></button><button id="pip-next" class="icon-button" aria-label="下一阶段">${icon('skip')}</button></div><div id="pip-status" class="pip-status"></div><div class="pip-clock" id="pip-clock"></div></main>`;doc.querySelector('#pip-toggle').onclick=toggle;doc.querySelector('#pip-next').onclick=()=>goNext(false);pipWindow.addEventListener('pagehide',()=>{pipWindow=null;});applyTheme();updatePip();toast('小窗已打开，切换到其他软件也能看到。');return;}
if(document.pictureInPictureEnabled&&HTMLCanvasElement.prototype.captureStream){pipCanvas=document.createElement('canvas');pipCanvas.width=640;pipCanvas.height=360;drawVideoPip();pipVideo=document.createElement('video');pipVideo.muted=true;pipVideo.playsInline=true;pipStream=pipCanvas.captureStream(2);pipVideo.srcObject=pipStream;await pipVideo.play();await pipVideo.requestPictureInPicture();pipVideo.addEventListener('leavepictureinpicture',()=>{pipStream?.getTracks().forEach(t=>t.stop());pipVideo=null;pipCanvas=null;});toast('已打开计时小窗，暂停等操作请回到主页面。');return;}toast('此浏览器不支持置顶小窗。请用桌面 Chrome 或 Edge 打开。');}catch{pipStream?.getTracks().forEach(t=>t.stop());pipVideo=null;pipCanvas=null;toast('小窗未能打开。请在独立的 Chrome 或 Edge 页面中点击「桌面小窗」。');}}
function updatePip(){if(pipWindow&&!pipWindow.closed){const doc=pipWindow.document;const q=s=>doc.querySelector(s);if(!q('#pip-time'))return;q('#pip-time').textContent=formatTime(remaining(timer));q('#pip-stage').textContent=`第 ${(timer.mode==='work'?timer.round+1:Math.max(1,timer.round))} 轮 · ${stageNames[timer.mode]}`;q('#pip-task').textContent=timer.mode==='work'?(activeTask()?.text||'此刻，只做一件事。'):'看看远方，放松一下。';q('#pip-toggle').innerHTML=icon(timer.running?'pause':'play')+`<span>${timer.running?'暂停':'开始'}</span>`;q('#pip-status').textContent=timer.handled?'本轮完成，点右侧按钮进入下一阶段。':'';q('#pip-clock').textContent=new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});doc.body.dataset.stage=timer.mode;paintPalette(doc.body,timer.mode);}if(pipCanvas)drawVideoPip();}
function drawVideoPip(){const c=pipCanvas.getContext('2d');c.fillStyle=palette(timer.mode).bg;c.fillRect(0,0,640,360);c.textAlign='center';c.fillStyle=palette(timer.mode).text;c.font='700 20px sans-serif';c.fillText(`TIDE · ${stageNames[timer.mode]}`,320,65);c.fillStyle=palette(timer.mode).text;c.font='800 112px Arial, sans-serif';c.fillText(formatTime(remaining(timer)),320,205);c.fillStyle=palette(timer.mode).muted;c.font='700 19px sans-serif';c.fillText((timer.handled?'本轮完成，记得休息一下':activeTask()?.text||'此刻，只做一件事。').slice(0,25),320,277);c.font='16px sans-serif';c.fillText(timer.running?'专注进行中':'已暂停 · 回到主页面继续',320,320);}
$('#pip-btn').onclick=openPip;$('#mini-pip').onclick=openPip;
applyTheme();renderTasks();tick();if(pendingSummary&&!$('#summary-dialog').open)openSummary(pendingSummary);setInterval(tick,500);
